 if(isset($_POST['toggle'])){$pdo->prepare("UPDATE diploma_programs SET status=IF(status='active','hidden','active') WHERE id=?")->execute([$id]);$_SESSION['flash']='শিক্ষাক্রমের প্রকাশের অবস্থা পরিবর্তন হয়েছে।';header('Location: diploma.php');exit;}
 $name=trim($_POST['technology_name']??'');$code=trim($_POST['code']??'');$image=trim((string)($_POST['existing_image']??($editing['image_path']??'assets/campus-5.jpg')));if(!empty($_FILES['program_image']['name'])){ $f=$_FILES['program_image']; if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){$error='ছবি আপলোড করা যায়নি। আবার চেষ্টা করুন।';} elseif(($f['size']??0)>5*1024*1024){$error='ছবির সর্বোচ্চ সাইজ ৫ MB।';} else { $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if($ext===''||!@getimagesize($f['tmp_name'])){$error='শুধু JPG, PNG অথবা WEBP ছবি আপলোড করুন।';}else{$dir=__DIR__.'/../uploads/site';if(!is_dir($dir))@mkdir($dir,0755,true);$fn='diploma-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$fn))$error='ছবি সার্ভারে সংরক্ষণ করা যায়নি।';else $image='live/uploads/site/'.$fn;}}}$session=trim($_POST['session_label']??'');$semester=trim($_POST['current_semester']??'');$description=trim($_POST['description']??'');$status=($_POST['status']??'active')==='hidden'?'hidden':'active';$sort=(int)($_POST['sort_order']??0);
